/**
 * Contributes to the shared additive `default = { ship_of_size_limits = ... }`
 * sink: ids this mod names but does not own, with no author-named file.
 * A ref listed twice is emitted once.
 */
export function addShipOfSizeLimits(
  shipOfSizeLimits: readonly (TypedRef<"country_ship_of_size_limit"> | string)[]
): ContributionItem {
  return {
    itemKind: "contribution",
    registry: "ship_of_size_limits",
    refRegistry: "country_ship_of_size_limit",
    ids: shipOfSizeLimits.map((entry) => String(refId(entry))),
  };
}
